function allowed(p){const a=roleAllowed[store.role];return !a||a.includes(p)}
function status(s){let c=/Activo|Activa|Autoriz|Cerrad|Ubicada|Exitoso/.test(s)?'success':/Por |preparación|Advertencia|Borrador|Confirmado/.test(s)?'warning':/Rechaz|Inconsistencia|Fallido/.test(s)?'error':'info';return `<span class="status ${c}">${I(c==='success'?'circle-check':c==='error'?'triangle-alert':c==='warning'?'clock-3':'info')} ${s}</span>`}
function showToast(title,text=''){store.toast={title,text};render();setTimeout(()=>{store.toast=null;render()},3200)}
function goto(page){if(!allowed(page))return;store.page=page;store.drawer=null;store.modal=null;render();window.scrollTo(0,0)}
function login(result='Exitoso'){store.audits.unshift(['13/10/2026 09:15:00',result==='Exitoso'?'Daniela Ríos':'Raúl Esquivel Montes','Inicio de sesión','Web · Chrome',result]);if(result==='Inactivo'){showToast('Tu usuario está inactivo en Cavas','Pide a tu administrador que lo reactive.');return}store.logged=true;store.page='inicio';render()}
function logout(reason='Cierre de sesión'){store.audits.unshift(['13/10/2026 09:15:00','Daniela Ríos',reason,'Web · Chrome','Exitoso']);store.logged=false;render()}
function loginView(){return `<main class="login"><section class="login-art"><div class="login-mark"><span class="eyebrow" style="color:#f1dce1">Sigma Foods · Cavas corporativas</span><h1>Cada botella sabe dónde está y por qué se movió.</h1><p>Trazabilidad confiable desde la recepción hasta el último brindis.</p></div></section><section class="login-panel"><div class="login-box"><div class="brand"><img src="SigmaLogo-cropped.png" alt="Sigma"><span class="brand-product">Cavas</span></div><h2>Bienvenida de nuevo</h2><p>Sistema de Administración de Cavas de Sigma Foods.</p><button class="btn primary" onclick="login()">${I('panel-top-open')} Iniciar sesión con Microsoft</button><p class="muted">Usa tu cuenta corporativa. Tu acceso se valida con Microsoft Entra ID.</p><button class="text-link" onclick="login('Inactivo')">Probar con usuario inactivo <small>· Solo prototipo</small></button></div></section></main>`}
function shell(content){let visible=nav.filter(n=>allowed(n[1]));let side=visible.map(n=>`${n[0]?`<div class="nav-group">${n[0]}</div>`:''}<button class="nav-item ${store.page===n[1]?'active':''}" onclick="goto('${n[1]}')">${I(n[3])}<span>${n[2]}</span>${n[4]==='IA'?'<span class="ai-chip">IA</span>':n[4]?`<span class="status neutral badge">${n[4]}</span>`:''}</button>`).join('');return `<div class="app-shell"><header class="topbar"><div class="brand"><img src="SigmaLogo-cropped.png" alt="Sigma"><span class="brand-product">Cavas</span></div><label class="global-search">${I('search')}<input placeholder="Busca botella, vino, lote, evento u orden" onkeydown="if(event.key==='Enter'){store.filters.query=this.value;goto('consultas')}"></label><div class="top-actions"><button class="btn" onclick="goto('escaneo')">${I('scan-line')} Escanear</button><button class="icon-btn" aria-label="Alertas" onclick="goto('inicio')">${I('bell')}<span class="counter">4</span></button><select class="role-select" aria-label="Ver como" onchange="store.role=this.value; if(!allowed(store.page))store.page='inicio';render()">${Object.keys(roleAllowed).map(r=>`<option ${r===store.role?'selected':''}>${r}</option>`).join('')}</select><button class="avatar" onclick="store.modal='profile';render()"><span class="avatar-circle">DR</span><span class="avatar-info"><strong>Daniela Ríos</strong><small>${store.role} · Solo prototipo</small></span></button></div></header><aside class="sidebar">${side}</aside><main class="main">${content}</main><nav class="bottom-nav">${[['inicio','house','Inicio'],['escaneo','scan-line','Escanear'],['eventos','calendar-days','Eventos'],['consultas','search','Consultas'],['menu','menu','Más']].map(x=>`<button class="${store.page===x[0]?'active':''}" onclick="${x[0]==='menu'?"store.modal='more';render()":`goto('${x[0]}')`}">${I(x[1])}${x[2]}</button>`).join('')}</nav>${overlay()}</div>`}
function pageHead(title,subtitle='',actions=''){return `<div class="page-head"><div><span class="eyebrow">Sigma Foods · Cavas</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="head-actions">${actions}</div></div>`}
function overlay(){let html='';if(store.drawer)html=`<div class="drawer-backdrop" onclick="if(event.target===this){store.drawer=null;render()}"><aside class="drawer">${store.drawer}</aside></div>`;if(store.modal==='profile')html+=`<div class="modal-backdrop" onclick="if(event.target===this){store.modal=null;render()}"><div class="modal"><div class="drawer-head"><div><span class="eyebrow">Sesión activa</span><h2>Daniela Ríos Salazar</h2><p class="muted">${store.role}</p></div><button class="close" onclick="store.modal=null;render()">${I('x')}</button></div><button class="nav-item">${I('user')} Mi perfil</button><button class="nav-item">${I('clock')} Zona horaria: America/Monterrey</button><button class="nav-item" onclick="store.modal='expire';render()">${I('timer')} Simular expiración de sesión</button><button class="nav-item" onclick="logout()">${I('log-out')} Cerrar sesión</button></div></div>`;if(store.modal==='expire')html+=confirmModal('Tu sesión expira en 2 minutos por inactividad','Guarda tus cambios para no perderlos.',`<button class="btn" onclick="logout('Expiración por inactividad')">Cerrar sesión</button><button class="btn primary" onclick="store.modal=null;render()">Seguir trabajando</button>`);if(store.modal==='more')html+=`<div class="modal-backdrop"><div class="modal"><div class="drawer-head"><h2>Más módulos</h2><button class="close" onclick="store.modal=null;render()">${I('x')}</button></div>${nav.filter(n=>allowed(n[1])).map(n=>`<button class="nav-item" onclick="goto('${n[1]}')">${I(n[3])}${n[2]}</button>`).join('')}</div></div>`;if(store.toast)html+=`<div class="toast"><strong>${store.toast.title}</strong>${store.toast.text}</div>`;return html}
function confirmModal(title,text,buttons){return `<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><p>${text}</p><p class="muted">Esta acción registra un movimiento y queda en bitácora.</p><div class="button-row" style="justify-content:flex-end">${buttons}</div></div></div>`}
function openDetail(type,id){const maps={cava:store.cavas,rack:store.racks,wine:store.wines,event:store.events,order:store.orders,adjustment:store.adjustments};const x=maps[type]?.find(a=>a.id===id||a.uid===id);if(type==='rack'){store.filters.rack=x.uid;goto('matriz');return}if(!x)return;let body=Object.entries(x).filter(([k])=>!['uid'].includes(k)).map(([k,v])=>`<div class="field"><label>${k.replace(/([A-Z])/g,' $1')}</label><div>${k==='estado'?status(v):`<strong>${v}</strong>`}</div></div>`).join('');store.drawer=`<div class="drawer-head"><div><span class="eyebrow">Detalle</span><h2 class="mono">${x.id||x.nombre}</h2><p>${x.nombre||x.evento||x.vino}</p></div><button class="close" onclick="store.drawer=null;render()">${I('x')}</button></div><div class="form-grid">${body}</div>${type==='event'?`<div class="tabs"><button class="tab active">Vinos</button><button class="tab">Órdenes</button><button class="tab">Historial</button></div><div class="card"><strong>Asignadas ${x.asignadas} · Utilizadas ${x.utilizadas} · Devueltas ${x.devueltas}</strong><p>${x.asignadas?'Costo utilizado US$ 540.00':'Este evento aún no tiene vinos asignados.'}</p></div>`:''}<div class="drawer-footer"><button class="btn danger" onclick="deactivate('${type}','${id}')">${I('archive')} Dar de baja</button><button class="btn primary" onclick="editRecord('${type}','${id}')">${I('pencil')} Editar</button></div>`;render()}
function editRecord(type,id){const maps={cava:store.cavas,wine:store.wines,event:store.events,order:store.orders,adjustment:store.adjustments};const x=maps[type]?.find(a=>a.id===id);if(!x)return;store.drawer=`<div class="drawer-head"><div><span class="eyebrow">Edición</span><h2>${x.nombre||x.id}</h2></div><button class="close" onclick="store.drawer=null;render()">${I('x')}</button></div><form onsubmit="event.preventDefault();saveEdit('${type}','${id}')"><div class="form-grid"><label class="field full"><span>Nombre o descripción</span><input id="edit-name" class="input" required value="${x.nombre||x.evento||x.vino||x.id}"></label><label class="field full"><span>Comentarios</span><textarea class="input" maxlength="500">Actualización operativa</textarea></label></div><div class="drawer-footer"><button class="btn" type="button" onclick="store.drawer=null;render()">Cancelar</button><button class="btn primary">Guardar cambios</button></div></form>`;render()}
function saveEdit(type,id){const maps={cava:store.cavas,wine:store.wines,event:store.events};const x=maps[type]?.find(a=>a.id===id);if(x)x.nombre=$('#edit-name').value;store.drawer=null;showToast('Cambios guardados',`${id} actualizado y registrado en auditoría.`)}
function deactivate(type,id){const maps={cava:store.cavas,wine:store.wines,event:store.events,order:store.orders,adjustment:store.adjustments};const x=maps[type]?.find(a=>a.id===id);if((type==='cava'&&x.ocupadas)||(type==='wine'&&x.existencia)){showToast('No se puede dar de baja',type==='cava'?`Tiene ${x.ocupadas} botellas ubicadas. Reubícalas primero.`:`Este vino tiene ${x.existencia} botellas en cava.`);return}x.estado='Inactivo';store.drawer=null;showToast(`${id} dado de baja`,'La historia se conserva y el cambio quedó en bitácora.')}
function table(headers,rows,onrow=''){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr ${onrow?`onclick="${onrow}('${r._id}')"`:''}>${headers.map(h=>`<td>${r[h]??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function exportXlsx(name,headers,rows){if(typeof XLSX==='undefined'){showToast('No se pudo exportar','La librería XLSX no está disponible.');return}const data=rows.map(r=>Object.fromEntries(headers.map(h=>[h,String(r[h]??'').replace(/<[^>]*>/g,'')])));const wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(data);XLSX.utils.book_append_sheet(wb,ws,'Datos');XLSX.writeFile(wb,`${name}.xlsx`);store.exports.unshift({fecha:'16/10/2026 12:05',usuario:'Daniela Ríos',reporte:name,filtros:'Filtros visibles',filas:rows.length,formato:'XLSX'});store.audits.unshift(['16/10/2026 12:05:00','Daniela Ríos','Exportar XLSX',name,'Exitoso']);showToast('Exportación registrada en bitácora.',`${rows.length} filas descargadas en formato XLSX.`)}
function exportCurrent(entity){let rows,headers,name;if(entity==='cavas'){headers=['Clave','Nombre','Ubicación','Anaqueles','Celdas','Ocupadas','Estado'];rows=store.cavas.map(x=>({Clave:x.id,Nombre:x.nombre,Ubicación:x.ubicacion,Anaqueles:x.anaqueles,Celdas:x.celdas,Ocupadas:x.ocupadas,Estado:x.estado}));name='Cavas'}else if(entity==='vinos'){headers=['Vino','Tipo','Origen','Grupos','Existencia','Estado'];rows=store.wines.map(x=>({Vino:x.nombre,Tipo:x.tipo,Origen:x.origen,Grupos:x.grupos,Existencia:x.existencia,Estado:x.estado}));name='Vinos'}else{headers=['Registro'];rows=[];name=entity}exportXlsx(name,headers,rows)}
function toolbar(entity,addFn){const label={cavas:'Nueva cava',vinos:'Nuevo vino'}[entity]||`Nuevo ${entity}`;return `<div class="toolbar"><input class="input" placeholder="Buscar en ${entity}" oninput="store.filters['${entity}']=this.value;render()" value="${store.filters[entity]||''}"><button class="btn" onclick="exportCurrent('${entity}')">${I('download')} Exportar XLSX</button><label class="btn"><input type="checkbox"> Mostrar inactivos</label><button class="btn primary" onclick="${addFn}">${I('plus')} ${label}</button></div>`}
function home(){return `<div class="page"><h1 class="narrative">Buenos días, Daniela. Hoy llegan 36 botellas nuevas y esperan su lugar.</h1><p class="muted">Martes 13 de octubre de 2026 · 09:15 · America/Monterrey</p><div class="kpi-grid">${[['Botellas ubicadas','679','wine'],['Por ubicar','41','map-pin'],['Ocupación','78.6%','gauge'],['Por consumir en 2026','18','clock-3'],['Inconsistencias abiertas','3','triangle-alert'],['Ajustes por autorizar','1','stamp']].map(k=>`<article class="kpi"><div class="kpi-top"><span>${k[0]}</span>${I(k[2])}</div><div class="kpi-value">${k[1]}</div><div class="kpi-note">${k[0]==='Ocupación'?'679 de 864 celdas':'Corte al 13/10/2026'}</div></article>`).join('')}</div><section class="card" style="margin-bottom:16px"><h2>Accesos rápidos</h2><div class="quick-grid">${[['Recibir lote','package-plus','recepcion'],['Escanear entrada','scan-line','escaneo'],['Escanear salida','log-out','salida'],['Nuevo evento','calendar-plus','eventos'],['Preguntar a la IA','sparkles','ia']].map(q=>`<button class="quick" onclick="goto('${q[2]}')">${I(q[1])}<br><strong>${q[0]}</strong></button>`).join('')}</div></section><div class="grid-2"><section class="card"><h2>Atención hoy</h2>${[['18 botellas deben consumirse en 2026','Ver botellas','reportes','warning'],['Lote LT-2026-0142: 36 botellas por ubicar','Ubicar ahora','escaneo','info'],['3 inconsistencias abiertas','Resolver','asignar','error'],['LT-2013-0027 lleva 12 años en preentrada','Revisar','asignar','warning']].map(a=>`<div class="alert-row"><span class="state-icon ${a[3]}">${I(a[3]==='error'?'triangle-alert':'clock-3')}</span><span>${a[0]}</span><button class="btn" onclick="goto('${a[2]}')">${a[1]}</button></div>`).join('')}</section><section class="card"><h2>Ocupación por cava</h2><div class="chart-row">${[['CAV-01',85.2],['CAV-02',67.4],['CAV-03',74.3]].map(b=>`<div class="bar-wrap"><div class="bar-value">${b[1]}%</div><div class="bar" style="height:${b[1]}%"></div><div>${b[0]}</div></div>`).join('')}</div></section><section class="card"><h2>Movimientos de los últimos 30 días</h2>${[['Entradas',48,'log-in'],['Salidas',52,'log-out'],['Devoluciones',6,'undo-2'],['Ajustes',2,'sliders-horizontal']].map(x=>`<div class="activity-row">${I(x[2])}<strong>${x[0]}</strong><span style="margin-left:auto;font-size:20px">${x[1]}</span></div>`).join('')}</section><section class="card"><h2>Próximos eventos</h2>${store.events.slice(3,6).map(e=>`<div class="event-row" onclick="openDetail('event','${e.id}')"><div><strong>${e.nombre}</strong><div class="muted">${e.fecha} · ${e.lugar}</div></div>${status(e.estado)}</div>`).join('')}</section></div></div>`}
function cavas(){let q=(store.filters.cavas||'').toLowerCase(),data=store.cavas.filter(x=>(x.nombre+x.ubicacion).toLowerCase().includes(q));let rows=data.map(x=>({_id:x.id,Clave:`<span class="mono">${x.id}</span>`,Nombre:x.nombre,Ubicación:x.ubicacion,Anaqueles:x.anaqueles,Celdas:x.celdas,Ocupadas:x.ocupadas,Ocupación:`<div>${(x.ocupadas/x.celdas*100||0).toFixed(1)}%</div><div class="progress"><span style="width:${x.ocupadas/x.celdas*100||0}%"></span></div>`,Estado:status(x.estado)}));return `<div class="page">${pageHead('Cavas','3 cavas · 13 anaqueles · 864 celdas · 679 ocupadas') }<div class="table-card">${toolbar('cavas',"newForm('cava')")}${table(['Clave','Nombre','Ubicación','Anaqueles','Celdas','Ocupadas','Ocupación','Estado'],rows,'id=>openDetail(\'cava\',id)')}</div></div>`}
function racks(){let cava=store.filters.rackCava||'',data=store.racks.filter(x=>!cava||x.cava===cava),rows=data.map(x=>({_id:x.uid,Clave:`<span class="mono">${x.id}</span>`,Nombre:x.nombre,Cava:x.cava,Filas:x.filas,Columnas:x.columnas,Celdas:x.celdas,Ocupadas:x.ocupadas,Ocupación:`${(x.ocupadas/x.celdas*100).toFixed(1)}%`,Estado:status(x.estado)}));return `<div class="page">${pageHead('Anaqueles','Administración de capacidad y ubicaciones')}<div class="table-card"><div class="toolbar"><select class="select" onchange="store.filters.rackCava=this.value;render()"><option value="">Todas las cavas</option>${store.cavas.map(c=>`<option ${c.id===cava?'selected':''}>${c.id}</option>`).join('')}</select><button class="btn" onclick="exportXlsx('Anaqueles',${JSON.stringify(Object.keys(rows[0]||{}).filter(k=>k!=='_id'))},${JSON.stringify(rows)})">${I('download')} Exportar XLSX</button><button class="btn primary" onclick="newForm('rack')">${I('plus')} Nuevo anaquel</button></div>${table(['Clave','Nombre','Cava','Filas','Columnas','Celdas','Ocupadas','Ocupación','Estado'],rows,'id=>openDetail(\'rack\',id)')}</div></div>`}
function wines(){let q=(store.filters.vinos||'').toLowerCase(),data=store.wines.filter(x=>(x.nombre+x.tipo+x.origen+x.grupos).toLowerCase().includes(q)),rows=data.map(x=>({_id:x.id,Vino:`<strong>${x.nombre}</strong>`,Tipo:x.tipo,Origen:x.origen,Grupos:x.grupos,Presentaciones:`<span class="mono">${x.presentacion}</span>`,Existencia:x.existencia,'Por ubicar':x.porUbicar,Estado:status(x.estado)}));return `<div class="page">${pageHead('Vinos','10 etiquetas representativas del inventario')}<div class="table-card">${toolbar('vinos',"newForm('wine')")}${table(['Vino','Tipo','Origen','Grupos','Presentaciones','Existencia','Por ubicar','Estado'],rows,'id=>openDetail(\'wine\',id)')}</div></div>`}
function newForm(type){let config={cava:['Nueva cava',[['Nombre','nombre'],['Ubicación','ubicacion'],['Comentarios','comentarios']]],rack:['Nuevo anaquel',[['Cava','cava'],['Nombre','nombre'],['Filas, A a Z','filas'],['Columnas, 1 a 20','columnas'],['Comentarios','comentarios']]],wine:['Nuevo vino',[['Vino','nombre'],['Tipo','tipo'],['País, región y subregión','origen'],['Grupos','grupos'],['Código de presentación','presentacion'],['Costo US$','costo']]],event:['Nuevo evento',[['Nombre','nombre'],['Fecha y hora','fecha'],['Lugar','lugar'],['Solicitante','solicitante'],['Invitados','invitados'],['Comentarios','comentarios']]],order:['Nueva orden',[['Evento','evento'],['Solicitante','solicitante'],['Motivo de salida','motivo'],['Botellas','botellas']]],adjustment:['Nuevo ajuste',[['Botella','botella'],['Motivo','motivo'],['Comentario, mínimo 20 caracteres','comentario'],['Evidencia','evidencia']]]}[type];store.drawer=`<div class="drawer-head"><div><span class="eyebrow">Nuevo registro</span><h2>${config[0]}</h2></div><button class="close" onclick="store.drawer=null;render()">${I('x')}</button></div>${type==='rack'?`<div class="stepper"><div class="step active"><span class="step-num">1</span> Datos</div><div class="step"><span class="step-num">2</span> Vista previa</div></div>`:''}<form onsubmit="event.preventDefault();saveNew('${type}')"><div class="form-grid">${config[1].map(([l,n],i)=>`<label class="field ${i===config[1].length-1?'full':''}"><span>${l}</span><input class="input" name="${n}" ${n==='comentarios'?'maxlength="500"':''} ${n==='comentario'?'minlength="20"':''} required></label>`).join('')}</div><div class="drawer-footer"><button type="button" class="btn" onclick="store.drawer=null;render()">Cancelar</button><button class="btn primary">Guardar</button></div></form>`;render()}
function saveNew(type){let fd=Object.fromEntries(new FormData(event.target));if(type==='cava'){if(store.cavas.some(c=>c.nombre.toLowerCase()===fd.nombre.toLowerCase())){showToast('Ya existe una cava con ese nombre.','Usa un nombre diferente.');return}let id=`CAV-${String(store.cavas.length+1).padStart(2,'0')}`;store.cavas.push({id,nombre:fd.nombre,ubicacion:fd.ubicacion,anaqueles:0,celdas:0,ocupadas:0,estado:'Activa'});store.drawer=null;showToast(`Cava ${id} creada.`,'Agrega su primer anaquel.');return}if(type==='rack'){let cava=store.cavas.find(c=>c.id===fd.cava)||store.cavas[0],filas=parseInt(fd.filas)||8,columnas=parseInt(fd.columnas)||6,id=`AN-${String(cava.anaqueles+1).padStart(2,'0')}`;store.racks.push({uid:`R${Date.now()}`,cava:cava.id,id,nombre:fd.nombre,filas,columnas,celdas:filas*columnas,ocupadas:0,estado:'Activo'});cava.anaqueles++;cava.celdas+=filas*columnas;store.drawer=null;showToast(`Anaquel ${id} creado.`,`${filas} filas × ${columnas} columnas = ${filas*columnas} celdas.`);return}if(type==='wine'){let id=`V-${String(store.wines.length+1).padStart(3,'0')}`;store.wines.push({id,nombre:fd.nombre,tipo:fd.tipo,origen:fd.origen,grupos:fd.grupos,presentacion:fd.presentacion,costo:+fd.costo,existencia:0,porUbicar:0,estado:'Activo'});store.drawer=null;showToast(`Vino ${id} creado.`,'Ya aparece en el catálogo con existencia 0.');return}if(type==='event'){let id=`LOCAL-${String(store.events.length-4).padStart(3,'0')}`;store.events.push({id,nombre:fd.nombre,fecha:fd.fecha,lugar:fd.lugar,solicitante:fd.solicitante,estado:'Borrador',asignadas:0,utilizadas:0,devueltas:0});store.drawer=null;showToast(`Evento ${id} creado.`,'El borrador ya está disponible para consulta.');return}if(type==='order'){let id=`OS-2026-${String(319+store.orders.length-3).padStart(4,'0')}`;store.orders.push({id,evento:fd.evento,solicitante:fd.solicitante,motivo:fd.motivo,botellas:+fd.botellas,costo:0,estado:'Borrador',fecha:'13/10/2026'});store.drawer=null;showToast(`Orden ${id} creada.`,'El borrador quedó listo para completar.');return}if(type==='adjustment'){let id='AJ-2026-0057';store.adjustments.push({id,tipo:'Salida',botella:fd.botella,vino:'Matarromera Reserva 2019',motivo:fd.motivo,solicito:'Jorge Salinas',fecha:'16/10/2026',estado:'Por autorizar',impacto:'−1 · −US$ 42.00'});store.drawer=null;showToast(`${id} creado.`,'Se envió a autorización y quedó registrado en auditoría.')}}
function matrix(){let rack=store.racks.find(r=>r.uid===(store.filters.rack||'R3'))||store.racks[3],rows='ABCDEFGHIJKL'.slice(0,rack.filas).split(''),cells=[];for(let ri=0;ri<rack.filas;ri++)for(let c=1;c<=rack.columnas;c++){let pos=`${rows[ri]}${c}`,state='occupied',wine='CM 3V',code=`BOT-${String(ri*6+c).padStart(4,'0')}`;if(rack.cava==='CAV-01'&&rack.id==='AN-04'){if(ri<=1)wine='CM 3V';else if(ri<=3)wine='MX Gran';else if(ri<=7){state='suggested';wine='LT-0142'}else if(ri<=9){state='consume';wine='ST Único';code=`BOT-0061-${String((ri-8)*6+c).padStart(3,'0')}`}else {wine='LAC Neb';if(pos==='L5'){state='issue';code='BOT-0098-011'}if(pos==='L6'){state='free';wine='Libre';code=''}}}else if(ri*6+c>rack.ocupadas){state='free';wine='Libre';code=''}cells.push({pos,state,wine,code})}return `<div class="page">${pageHead(`${rack.id} ${rack.nombre}`,`${rack.cava} · ${rack.filas} filas × ${rack.columnas} columnas · ${rack.ocupadas} de ${rack.celdas} ocupadas (${(rack.ocupadas/rack.celdas*100).toFixed(1)}%)`,`<button class="btn">${I('printer')} Imprimir etiquetas</button><button class="btn" onclick="exportXlsx('Matriz ${rack.id}',['Celda','Estado'],${JSON.stringify(cells.map(c=>({Celda:c.pos,Estado:c.state})))})">${I('download')} Exportar XLSX</button>`)}<div class="toolbar card"><select class="select"><option>Todos los vinos</option><option>Casa Madero 3V</option></select><select class="select"><option>Todas las añadas</option><option>2021</option></select><label class="btn"><input type="checkbox"> Solo libres</label></div><div class="legend"><span><i class="dot"></i> Libre</span><span><i class="dot occupied"></i> Ocupada</span><span><i class="dot suggested"></i> Sugerida para lote</span><span><i class="dot consume"></i> Consumir pronto</span><span><i class="dot issue"></i> Inconsistencia</span></div><div class="matrix-wrap"><div class="matrix"><div></div>${Array.from({length:rack.columnas},(_,i)=>`<div class="matrix-head">${i+1}</div>`).join('')}${rows.map((r,ri)=>`<div class="matrix-head">${r}</div>${cells.slice(ri*6,ri*6+6).map(c=>`<button class="cell ${c.state}" onclick="cellDetail('${c.pos}','${c.state}','${c.code}','${c.wine}')"><span class="cell-code">${c.pos}</span>${c.code?`${I(c.state==='issue'?'triangle-alert':c.state==='consume'?'clock-3':'wine')} ${c.wine}<br><span class="mono">${c.code.replace('BOT-','')}</span>`:'Libre'}</button>`).join('')}`).join('')}</div></div><p class="muted">Capacidad por celda: 1 botella. Una celda ocupada no acepta otra botella.</p></div>`}
function cellDetail(pos,state,code,wine){store.drawer=`<div class="drawer-head"><div><span class="eyebrow">Celda</span><h2 class="mono">${pos}</h2></div><button class="close" onclick="store.drawer=null;render()">${I('x')}</button></div>${state==='free'||state==='suggested'?`<div class="empty">${I('wine')}<h3>Esta celda está libre</h3><p>${state==='suggested'?'Sugerida para LT-2026-0142.':'Lista para recibir una botella.'}</p><button class="btn primary" onclick="goto('escaneo')">Ubicar botella aquí</button></div>`:`<div class="card"><span class="mono">${code}</span><h2>${wine}</h2><p>Añada 2019 · 750 ml</p>${status(state==='issue'?'Inconsistencia':state==='consume'?'Consumir pronto':'Ubicada')}</div>${state==='issue'?`<div class="scan-result error">${I('triangle-alert')}<div><strong>Salida registrada, ubicación todavía ocupada</strong><p>Libera la celda conservando el movimiento original.</p></div></div>`:''}<div class="drawer-footer"><button class="btn">Ver historial</button><button class="btn primary" onclick="goto('${state==='issue'?'asignar':'consultas'}')">${state==='issue'?'Resolver en Asignar y ubicar':'Mover a otra celda'}</button></div>`}`;render()}
function events(){let rows=store.events.map(e=>({_id:e.id,Evento:`<strong>${e.nombre}</strong><br><span class="mono">${e.id}</span>`,Fecha:e.fecha,Lugar:e.lugar,Solicitante:e.solicitante,Estado:status(e.estado),Asignadas:e.asignadas,Utilizadas:e.utilizadas,Devueltas:e.devueltas,'ID Sistema':e.id.startsWith('EVT')?e.id:'Sin vínculo'}));return `<div class="page">${pageHead('Eventos','Agenda y consumo por evento',`<button class="btn" onclick="showToast('Sistema de Eventos','Se encontraron EVT-58213 y EVT-58301.')">${I('link')} Vincular desde Sistema de Eventos</button><button class="btn primary" onclick="newForm('event')">${I('plus')} Nuevo evento</button>`)}<div class="table-card"><div class="toolbar"><select class="select" onchange="store.filters.eventStatus=this.value;render()"><option>Todos los estados</option><option>Borrador</option><option>Confirmado</option><option>Cerrado</option></select><input class="input" type="date"><input class="input" type="date"></div>${table(['Evento','Fecha','Lugar','Solicitante','Estado','Asignadas','Utilizadas','Devueltas','ID Sistema'],rows,'id=>openDetail(\'event\',id)')}</div></div>`}
function orders(){let rows=store.orders.map(o=>({_id:o.id,Folio:`<span class="mono">${o.id}</span>`,Evento:o.evento,Solicitante:o.solicitante,Motivo:o.motivo,Botellas:o.botellas,Costo:store.role==='Solicitante'||store.role==='Operador de cava'?'Sin permiso':money(o.costo),Estatus:status(o.estado),Fecha:o.fecha}));return `<div class="page">${pageHead('Órdenes de salida','Preparación, autorización y surtido',`<button class="btn primary" onclick="newForm('order')">${I('plus')} Nueva orden</button>`)}<div class="table-card">${table(['Folio','Evento','Solicitante','Motivo','Botellas','Costo','Estatus','Fecha'],rows,'id=>openDetail(\'order\',id)')}</div></div>`}
function adjustments(){let active=store.activeTab||'Todos',data=active==='Todos'?store.adjustments:store.adjustments.filter(a=>active==='Por autorizar'?a.estado==='Por autorizar':active==='Autorizados'?a.estado==='Autorizado':a.estado==='Rechazado'),rows=data.map(a=>({_id:a.id,Folio:`<span class="mono">${a.id}</span>`,Tipo:a.tipo,Botella:`<span class="mono">${a.botella}</span>`,Vino:a.vino,Motivo:a.motivo,Solicitó:a.solicito,Fecha:a.fecha,Impacto:a.impacto,Estado:status(a.estado)}));return `<div class="page">${pageHead('Ajustes de inventario','Todo ajuste requiere evidencia y autorización',`<button class="btn primary" onclick="newForm('adjustment')">${I('plus')} Nuevo ajuste</button>`)}<div class="tabs">${[['Por autorizar',store.adjustments.filter(a=>a.estado==='Por autorizar').length],['Autorizados',2],['Rechazados',1],['Todos',store.adjustments.length]].map(t=>`<button class="tab ${active===t[0]?'active':''}" onclick="store.activeTab='${t[0]}';render()">${t[0]} (${t[1]})</button>`).join('')}</div><div class="table-card">${table(['Folio','Tipo','Botella','Vino','Motivo','Solicitó','Fecha','Impacto','Estado'],rows,'id=>openDetail(\'adjustment\',id)')}</div></div>`}
function scan(mode='entrada'){let isOut=mode==='salida',title=isOut?'Escaneo de salida':'Escaneo',subtitle=isOut?'OS-2026-0318 · Cena del Consejo de Administración':'Lote LT-2026-0142 · 36 botellas por ubicar';return `<div class="page">${pageHead(title,subtitle)}<div class="tabs"><button class="tab ${!isOut?'active':''}" onclick="goto('escaneo')">Entrada</button><button class="tab ${isOut?'active':''}" onclick="goto('salida')">Salida</button><button class="tab" onclick="goto('devolucion')">Devolución</button></div>${isOut?`<div class="card" style="margin-bottom:16px"><div class="grid-2"><div><span class="eyebrow">Orden</span><h2 class="mono">OS-2026-0318</h2><p>Cena del Consejo de Administración</p><p>Solicitante: Mariana Treviño Garza</p></div><label class="field"><span>Motivo de salida, obligatorio</span><select class="select" id="scan-reason"><option>Evento corporativo</option><option>Obsequio institucional</option><option>Degustación interna</option></select></label></div></div>`:''}<div class="scan-shell"><section class="card"><label class="field"><span>Código de botella</span><input autofocus class="scan-input mono" id="scan-code" placeholder="Escanea o escribe el código" onkeydown="if(event.key==='Enter')doScan('${mode}')"></label><div class="button-row" style="margin-top:10px"><button class="btn" onclick="doScan('${mode}')">${I('scan-line')} Validar código</button><button class="btn">${I('camera')} Usar cámara</button></div><p class="muted">Compatible con lector USB o Bluetooth</p>${store.scanResult?`<div class="scan-result ${store.scanResult.kind}">${I(store.scanResult.kind==='success'?'circle-check':'triangle-alert')}<div><strong>${store.scanResult.title}</strong><p>${store.scanResult.text}</p></div></div>`:''}</section><aside class="card"><h2>Progreso</h2>${isOut?`<p>Monte Xanic Chenin Colombard <strong>0/8</strong></p><div class="progress"><span style="width:0"></span></div><p>Santo Tomás Único <strong>0/12</strong></p><div class="progress"><span style="width:0"></span></div><p>Matarromera Reserva <strong>0/4</strong></p>`:`<p>Casa Madero 3V <strong>6 de 24 ubicadas</strong></p><div class="progress"><span style="width:25%"></span></div><p>Monte Xanic Chenin Colombard <strong>0 de 12</strong></p>`}<h2 style="margin-top:24px">Últimos escaneos</h2><ul class="scan-list">${store.scanLog.map(x=>`<li><span class="mono">${x.code}</span><span>${x.time}</span></li>`).join('')||'<li class="muted">Aún no hay lecturas</li>'}</ul></aside></div></div>`}
function doScan(mode){let code=($('#scan-code')?.value||'').trim().toUpperCase();if(!code)code=mode==='salida'?'BOT-0061-001':'BOT-0142-006';let result;if(mode==='salida'){if(code==='BOT-0061-007')result={kind:'error',title:'Salida duplicada',text:'BOT-0061-007 ya tiene salida registrada hoy a las 17:41 en OS-2026-0318. No se registró de nuevo.'};else if(code==='BOT-0142-003')result={kind:'error',title:'Botella fuera de la orden',text:'BOT-0142-003 no forma parte de OS-2026-0318. Devuélvela a AN-04 · E3.'};else result={kind:'success',title:`${code} · Salida registrada`,text:'Santo Tomás Único 2018 · AN-04 · I1. Celda liberada.'}}else{if(code==='E3'||code==='BOT-0142-003')result={kind:'error',title:'La celda E3 ya está ocupada',text:'Contiene BOT-0142-003. Elige otra celda libre.'};else result={kind:'success',title:`${code} ubicada en AN-04 · E6`,text:'Entrada confirmada. Siguiente ubicación consecutiva: AN-04 · F1.'}}store.scanResult=result;store.scanLog.unshift({code,time:'10:04'});render()}
